#include "nova64/bus/bus.hpp"
#include "nova64/memory/rdram.hpp"
#include "nova64/memory/mmio.hpp"
#include "nova64/cartridge/rom.hpp"
#include <stdexcept>
namespace nova64 { Bus::Bus(uint32_t n):ram_(std::make_unique<Rdram>(n)),mmio_(std::make_unique<Mmio>()){} void Bus::attach_rom(std::shared_ptr<const RomImage> r){rom_=std::move(r);} Rdram& Bus::ram(){return *ram_;} uint64_t Bus::read(uint64_t a,AccessSize z){uint32_t x=uint32_t(a&0x1fffffff);if(x<ram_->size()){if(z==AccessSize::U8)return ram_->read8(x);if(z==AccessSize::U16)return ram_->read16(x);if(z==AccessSize::U32)return ram_->read32(x);return ram_->read64(x);}if(a>=0x10000000&&a<0x10000000+(rom_?rom_->size():0)){uint64_t v=0;for(unsigned i=0;i<unsigned(z);++i)v=(v<<8)|rom_->read8(uint32_t(a-0x10000000+i));return v;}if(z==AccessSize::U32)return mmio_->read32(uint32_t(a));throw std::out_of_range("Bus read unmapped");} void Bus::write(uint64_t a,uint64_t v,AccessSize z){uint32_t x=uint32_t(a&0x1fffffff);if(x<ram_->size()){if(z==AccessSize::U8)ram_->write8(x,v);else if(z==AccessSize::U16)ram_->write16(x,v);else if(z==AccessSize::U32)ram_->write32(x,v);else ram_->write64(x,v);return;}if(z==AccessSize::U32){mmio_->write32(uint32_t(a),uint32_t(v));return;}throw std::out_of_range("Bus write unmapped");} }
